get() {
      native.record(`get:getTime:${label}`, { sameReceiver: this === value });
      assert.notEqual(label, "excluded", "Provider filtering must precede timestamp consumption");
      if (index === 0 && name === "get-time-getter-error")
        throw original;
      return function getTime(...args) {
        native.call(`call:getTime:${label}`, this, value, args);
        methodCalls += 1;
        if (index === 0 && name === "get-time-method-error" || index === 1 && name === "later-method-precedes-conversion-error")
          throw original;
        if (["deferred-number-conversion", "value-of-error", "later-method-precedes-conversion-error"].includes(name))
          return numberResult;
        if (name === "nan-stable-order")
          return;
        if (name === "infinity-stable-order")
          return 1 / 0;
        return index === 0 ? "5" : "9";
      };
    }

